    linear_extrude(height = block_height, scale = top_size / base_size)
        square([base_size, base_size], center = true);
}

// ---------- Pocket ----------
module pocket() {
    translate([0, 0, block_height - pocket_depth])
        linear_extrude(height = pocket_depth + cut_extra)
            square([pocket_size, pocket_size], center = true);
}

// ---------- Part ----------
difference() {
    frustum();
    pocket();
}

// Tapered riser block - square frustum with top pocket
// Print orientation: base on bed (z = 0), builds upward

base_size   = 60;   // bottom square side (mm)
top_size    = 30;   // top square side (mm)
height      = 20;   // total height (mm)
pocket_size = 20;   // pocket square side (mm)
pocket_depth = 5;   // pocket depth (mm)
eps         = 0.5;  // cutter overshoot (mm)

difference() {
    // Square frustum: cylinder with 4 sides, rotated 45 deg so edges align with X/Y.
    // Circumradius = side / sqrt(2)
    rotate([0, 0, 45])
        cylinder(h = height,
                 r1 = base_size / sqrt(2),
                 r2 = top_size / sqrt(2),
                 $fn = 4);

    // Centred square pocket in the top face
    translate([-pocket_size / 2, -pocket_size / 2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}

// Tapered riser block for raising a beaker
// Solid square frustum with a square pocket in the top face

// ---- Dimensions (mm) ----
