top_size     = 50;   // top square side length
height       = 25;   // overall height
pocket_size  = 40;   // square pocket side length
pocket_depth = 5;    // pocket depth from top face
eps          = 0.5;  // overcut for clean boolean differences

$fn = 64;

difference() {
    // Square frustum: hull of thin slabs at bottom and top
    hull() {
        translate([-base_size/2, -base_size/2, 0])
            cube([base_size, base_size, 0.01]);
        translate([-top_size/2, -top_size/2, height - 0.01])
            cube([top_size, top_size, 0.01]);
    }

    // Centred square pocket in the top face
    translate([-pocket_size/2, -pocket_size/2, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}

// Cabinet door pull handle
// Print orientation: posts standing on the bed (z = 0), bar on top (z = 30..36)

$fn = 64;

// --- Posts ---
post_d       = 14;    // post diameter
post_h       = 30;    // post height (z = 0 to 30)
post_x       = 32;    // post axis offset from origin in X (posts at +/-32)

// --- Bar ---
bar_l        = 78;    // bar length (X)
bar_w        = 14;    // bar width (Y)
bar_t        = 6;     // bar thickness (Z), z = 30 to 36

// --- Screw holes ---
hole_d       = 4.5;   // screw hole diameter
hole_depth   = 10;    // hole depth from bottom face

// --- Misc ---
eps          = 0.5;   // overshoot for clean boolean cuts
overlap      = 0.01;  // small overlap so posts fuse with bar

difference() {
    union() {
        // Posts
        for (sx = [-1, 1])
            translate([sx * post_x, 0, 0])
                cylinder(d = post_d, h = post_h + overlap);

        // Bar
        translate([-bar_l / 2, -bar_w / 2, post_h])
            cube([bar_l, bar_w, bar_t]);
    }

    // Screw holes up each post axis from the bottom face
    for (sx = [-1, 1])
        translate([sx * post_x, 0, -eps])
            cylinder(d = hole_d, h = hole_depth + eps);
