pocket_depth = 8;    // pocket depth from top face

eps          = 0.5;  // overcut so cutting faces are not coplanar

$fn = 64;

module frustum() {
    // Square frustum via linear_extrude with scale, centred on origin
    linear_extrude(height = height, scale = top_size / bottom_size)
        square([bottom_size, bottom_size], center = true);
}

