// Solid square frustum, edges parallel to X and Y
module frustum() {
    hull() {
        translate([-base_size/2, -base_size/2, 0])
            cube([base_size, base_size, 0.01]);
        translate([-top_size/2, -top_size/2, height - 0.01])
            cube([top_size, top_size, 0.01]);
