// ---- Frustum as polyhedron ----
module frustum(bw, tw, h) {
    b = bw / 2;
    t = tw / 2;
    polyhedron(
        points = [
            [-b, -b, 0], [ b, -b, 0], [ b,  b, 0], [-b,  b, 0],   // bottom 0-3
            [-t, -t, h], [ t, -t, h], [ t,  t, h], [-t,  t, h]    // top 4-7
        ],
        faces = [
            [0, 1, 2, 3],   // bottom
            [4, 5, 1, 0],   // front (-Y)
            [5, 6, 2, 1],   // right (+X)
            [6, 7, 3, 2],   // back (+Y)
            [7, 4, 0, 3],   // left (-X)
            [7, 6, 5, 4]    // top
        ]
    );
}

