axle_d       = 8;    // axle hole diameter
spoke_count  = 8;    // number of spokes
spoke_width  = 4;    // spoke width (tangential)
eps          = 0.5;  // cutter overshoot

// ---- Derived ----
rim_id       = rim_od - 2 * rim_width;          // rim inner diameter (50)
spoke_start  = axle_d / 2 + 1;                  // start inside hub (overlap)
spoke_end    = rim_id / 2 + rim_width / 2;      // end inside rim (overlap)

