        ],
        faces = [
            [0, 1, 2, 3],   // bottom
            [4, 7, 6, 5],   // top
            [0, 4, 5, 1],   // front (-Y)
            [1, 5, 6, 2],   // right (+X)
            [2, 6, 7, 3],   // back (+Y)
            [3, 7, 4, 0]    // left (-X)
        ]
    );
}

