    [-x_trans,  -hw_grip],
    [-x_gauge,  -hw_gauge],
    [ x_gauge,  -hw_gauge],
    [ x_trans,  -hw_grip],
    [ x_end,    -hw_grip],
    [ x_end,     hw_grip],
    [ x_trans,   hw_grip],
    [ x_gauge,   hw_gauge],
    [-x_gauge,   hw_gauge],
    [-x_trans,   hw_grip],
    [-x_end,     hw_grip]
];

// ---------------- Part ----------------
linear_extrude(height = thickness)
    polygon(points = outline);

// Flat tensile test specimen (dog bone) for printed plastic
// Lies flat on the bed, symmetric about the origin, length along X

$fn = 64;

// ---------------- Dimensions (mm) ----------------
thickness      = 4;    // specimen thickness (Z)
total_length   = 130;  // overall length (X)
gauge_width    = 6;    // narrow gauge section width (Y)
gauge_length   = 30;   // gauge section length (X)
grip_width     = 20;   // grip section width (Y)
grip_length    = 35;   // grip section length (X), each end
trans_length   = 15;   // transition length (X), each side, linear taper

// ---------------- Derived values ----------------
x_gauge = gauge_length / 2;                 // end of gauge section
x_trans = x_gauge + trans_length;           // end of transition / start of grip
x_end   = x_trans + grip_length;            // end of specimen (= total_length/2)
hg = gauge_width / 2;                       // half gauge width
hw = grip_width / 2;                        // half grip width

// Sanity check: section lengths must add up to total length
assert(abs(2 * x_end - total_length) < 1e-6,
       "Section lengths do not sum to total_length");

// ---------------- Outline (seen from above) ----------------
outline = [
    [-x_end,   -hw],
    [-x_trans, -hw],
    [-x_gauge, -hg],
    [ x_gauge, -hg],
    [ x_trans, -hw],
    [ x_end,   -hw],
    [ x_end,    hw],
    [ x_trans,  hw],
    [ x_gauge,  hg],
    [-x_gauge,  hg],
    [-x_trans,  hw],
    [-x_end,    hw]
];

// ---------------- Model ----------------
linear_extrude(height = thickness)
    polygon(points = outline);

// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, centred on the origin

$fn = 128;

// ---- Dimensions (mm) ----
thickness    = 5;    // overall wheel thickness (Z)
rim_od       = 60;   // rim outer diameter
rim_width    = 6;    // rim radial width
hub_d        = 16;   // hub diameter
axle_d       = 6;    // axle hole diameter
spoke_count  = 5;    // number of spokes
spoke_width  = 4;    // spoke width
spoke_start  = 0;    // angle of first spoke (deg, along +X)

// ---- Derived ----
rim_id       = rim_od - 2 * rim_width;   // rim inner diameter (48 mm)
eps          = 0.5;                      // cutter overshoot
spoke_r0     = hub_d / 2 - 1;            // spoke starts inside hub (overlap)
spoke_r1     = rim_id / 2 + 1;           // spoke ends inside rim (overlap)

difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start + i * 360 / spoke_count])
                translate([spoke_r0, -spoke_width / 2, 0])
                    cube([spoke_r1 - spoke_r0, spoke_width, thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}

// Spoked wheel for a small sample cart
// Print orientation: flat on the bed, z = 0 up to z = thickness

$fn = 128;

// ---- Dimensions (mm) ----
thickness     = 5;    // overall wheel thickness (Z)
rim_od        = 60;   // rim outer diameter
rim_width     = 5;    // radial width of the rim ring
hub_d         = 20;   // hub diameter
axle_d        = 8;    // axle hole diameter
spoke_count   = 4;    // number of spokes
spoke_width   = 4;    // spoke width
spoke_start_a = 0;    // first spoke angle (deg), along +X

// ---- Derived ----
rim_id    = rim_od - 2 * rim_width;   // rim inner diameter
eps       = 0.5;                      // cutter overshoot
spoke_r0  = hub_d / 2 - 1;            // spoke starts inside hub (overlap)
spoke_r1  = rim_id / 2 + 1;           // spoke ends inside rim (overlap)

module rim() {
    difference() {
        cylinder(d = rim_od, h = thickness);
        translate([0, 0, -eps])
            cylinder(d = rim_id, h = thickness + 2 * eps);
    }
}

module hub() {
    cylinder(d = hub_d, h = thickness);
}

module spokes() {
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, spoke_start_a + i * 360 / spoke_count])
            translate([spoke_r0, -spoke_width / 2, 0])
                cube([spoke_r1 - spoke_r0, spoke_width, thickness]);
}

difference() {
    union() {
        rim();
        hub();
        spokes();
    }
    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}

