// Spoked wheel for a small sample cart
// Print orientation: flat on bed, centred on origin

$fn = 128;

// ---- Dimensions (mm) ----
wheel_thickness = 8;    // overall thickness (Z)
rim_od          = 60;   // rim outer diameter
rim_width       = 4;    // rim radial width
hub_d           = 14;   // hub diameter
axle_d          = 6;    // axle hole diameter
spoke_count     = 6;    // number of spokes
spoke_width     = 5;    // spoke width
spoke_start_ang = 0;    // first spoke along +X

// ---- Derived ----
rim_or  = rim_od / 2;
rim_ir  = rim_or - rim_width;
hub_r   = hub_d / 2;
eps     = 0.5;          // cutter overshoot

// Spoke length: from hub centre region into rim (overlaps both for solid union)
spoke_inner = hub_r - 1;          // starts inside hub
spoke_outer = rim_ir + rim_width/2; // ends inside rim

difference() {
    union() {
        // Rim
        difference() {
            cylinder(h = wheel_thickness, r = rim_or);
            translate([0, 0, -eps])
                cylinder(h = wheel_thickness + 2*eps, r = rim_ir);
        }

        // Hub
        cylinder(h = wheel_thickness, r = hub_r);

        // Spokes
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, spoke_start_ang + i * 360 / spoke_count])
                translate([spoke_inner, -spoke_width/2, 0])
                    cube([spoke_outer - spoke_inner, spoke_width, wheel_thickness]);
    }

    // Axle hole
    translate([0, 0, -eps])
        cylinder(h = wheel_thickness + 2*eps, d = axle_d);
}

